head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > adaptive]<br/>웹브라우저의 너비가 변경될 때 GridView 컴포넌트에 적응형 웹(Adaptive Web) 방식으로 적용될 레이아웃을 설정합니다.",
    "validation" : [
        "적응형 웹(Adaptive Web)은 Header 의 MultiLine <= 3 조건을 만족해야 적용되어야 합니다.",
        "적응형 웹(Adaptive Web)은 Body 의 MultiLine <= 2 조건을 만족해야 적용되어야 합니다.",
        "적응형 웹(Adaptive Web)은 SubTotal 의 MultiLine <= 3 조건을 만족해야 적용되어야 합니다.",
        "적응형 웹(Adaptive Web)은 Header 의 MultiLine + max(Body 의 MultiLine, SubTotal 의 MultiLine) 값이 4 이하일때 적용되어야 합니다."
    ]
}



scwin.gVar = { "headCnt": 1, "bodyCnt": 1, "subCnt": 0 };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_headerMultiLine.setValue("1");
    con_bodyMultiLine.setValue("1");
    con_subTotalMultiLine.setValue("0");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - adaptive="crosstab" / groupbyZone=false / adaptiveThreshold=9999(브라우저 너비 조건 항상 충족) 은 고정 전제
//  - Header / gBody / subTotal 의 w2:row 개수(MultiLine) 만 con 값으로 조립하여 적응형 적용 경계를 관측
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    // 테스트 참고 라벨 (target 생성 전, 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] adaptive=crosstab, groupbyZone=false, adaptiveThreshold=9999 (브라우저 너비 조건은 항상 충족)\n[절차] Header / Body / SubTotal 의 MultiLine (각 영역의 w2:row 개수) 을 선택하고 Target 재생성. SubTotal MultiLine 0 은 SubTotal 영역 없음\n[확인] (적응형 적용 여부 확인) 버튼으로 w2grid_adaptive_crosstab 클래스 적용 여부를 확인"', '', 'label1');

    // con 값(MultiLine 개수) 읽기
    let headCnt = parseInt(con_headerMultiLine.getValue(), 10) || 1;
    let bodyCnt = parseInt(con_bodyMultiLine.getValue(), 10) || 1;
    let subCnt = parseInt(con_subTotalMultiLine.getValue(), 10) || 0;
    scwin.gVar = { "headCnt": headCnt, "bodyCnt": bodyCnt, "subCnt": subCnt };

    let strNameSpace = $c.gcm.getNameSpace();

    // Body MultiLine 최대 3줄 x 2Column = 6개 Column 을 바인딩할 DataList 동적 생성
    //  - c1 은 SubTotal 그룹 기준 Column (A / B 2개 그룹)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    for (let i = 1; i <= 6; i++) {
        strDlt += '<w2:column id="c' + i + '" name="c' + i + '" dataType="text"></w2:column>';
    }
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [];
    for (let r = 1; r <= 4; r++) {
        let row = { "c1": (r <= 2 ? "A" : "B") };
        for (let i = 2; i <= 6; i++) {
            row["c" + i] = "c" + i + "_" + r;
        }
        jsonData.push(row);
    }
    dlt_bind.setJSON(jsonData, false);

    // Property 설정
    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' adaptive="crosstab" adaptiveThreshold="9999" groupbyZone="false" checkAllType="false" id="" style="width:100%;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="adaptive MultiLine 조건 테스트 그리드"></w2:caption>';

    // Header MultiLine
    strTarget += '<w2:header style="" id="header1">';
    for (let i = 1; i <= headCnt; i++) {
        strTarget += '<w2:row style="" id="hrow' + i + '">';
        strTarget += '<w2:column width="150" style="" inputType="text" id="hcol' + i + '_1" value="Header' + i + '-1"></w2:column>';
        strTarget += '<w2:column width="150" style="" inputType="text" id="hcol' + i + '_2" value="Header' + i + '-2"></w2:column>';
        strTarget += '</w2:row>';
    }
    strTarget += '</w2:header>';

    // Body MultiLine (Column id 는 DataList Column id 와 일치)
    strTarget += '<w2:gBody style="" id="gBody1">';
    for (let i = 1; i <= bodyCnt; i++) {
        strTarget += '<w2:row style="" id="brow' + i + '">';
        strTarget += '<w2:column width="150" style="" inputType="text" id="c' + (i * 2 - 1) + '"></w2:column>';
        strTarget += '<w2:column width="150" style="" inputType="text" id="c' + (i * 2) + '"></w2:column>';
        strTarget += '</w2:row>';
    }
    strTarget += '</w2:gBody>';

    // SubTotal MultiLine (0 이면 SubTotal 영역 미생성)
    if (subCnt > 0) {
        strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="c1">';
        for (let i = 1; i <= subCnt; i++) {
            strTarget += '<w2:row style="" id="srow' + i + '">';
            strTarget += '<w2:column width="150" style="" inputType="text" id="scol' + i + '_1" value="SubTotal' + i + '-1"></w2:column>';
            strTarget += '<w2:column width="150" style="" inputType="text" id="scol' + i + '_2" value="SubTotal' + i + '-2"></w2:column>';
            strTarget += '</w2:row>';
        }
        strTarget += '</w2:subTotal>';
    }

    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 적응형 crosstab 적용 여부 확인 (w2grid_adaptive_crosstab 클래스 유무로 실측)
scwin.btn_adaptiveCheck_onclick = function () {
    let isAdaptive = target1.hasClass("w2grid_adaptive_crosstab");
    wf_body_bottom.getObj("scwin").setReturnValue("[Header " + scwin.gVar.headCnt + " / Body " + scwin.gVar.bodyCnt + " / SubTotal " + scwin.gVar.subCnt + "] 적응형 crosstab 적용 : " + isAdaptive);
}
